"""Second question types for the last single-type frameworks (Nov 2026): Earth and Space (ES), Particle Physics (PP),
Nuclear (NU) and NCLEX-RN (NR). Numbers are verified along another route (escalc's orbit, Wien, luminosity, decay and
climate helpers; nursing.py's GCS and APGAR tables; sympy). Facts are authored; nursing facts are standard entry-level
content, with "usual" where practice varies."""
from opl_dsl import Q

FILE = "sci-second-types"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
ORB, STAR, COS, CLIM, HIST, INT, RES = ("space.orbits", "space.stars", "space.cosmology", "earth.climate", "earth.history",
                                        "earth.interior", "earth.resources")
PART, NDEC, NRAD, NCRIT, NOP, NKIN = "physics.particles", "nuc.decay", "nuc.radiation", "nuc.criticality", "nuc.operation", "nuc.kinetics"
NS, NM, NH, NPS, NB, NP, NRR, NPH, ND = ("nurs.safety", "nurs.management", "nurs.health-promotion", "nurs.psychosocial", "nurs.basic-care",
                                         "nurs.pharm", "nurs.risk-reduction", "nurs.physiological", "nurs.dosage")


def facts(name, skill, rows, explain, pace="quick"):
    return Q(name, skill, "{{q}}", pace=pace, cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


